class LRUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        # Doubly linked list nodes: key -> (prev_key, next_key)
        self.prev = {}
        self.next = {}
        # Head and tail dummy nodes
        self.head = None
        self.tail = None

    def _remove(self, key: str):
        p = self.prev[key]
        n = self.next[key]
        if p is not None:
            self.next[p] = n
        else:
            self.head = n
        if n is not None:
            self.prev[n] = p
        else:
            self.tail = p
        del self.prev[key]
        del self.next[key]

    def _add_to_front(self, key: str):
        self.prev[key] = None
        self.next[key] = self.head
        if self.head is not None:
            self.prev[self.head] = key
        self.head = key
        if self.tail is None:
            self.tail = key

    def get(self, key: str):
        if key not in self.cache:
            return -1
        # Move to front
        self._remove(key)
        self._add_to_front(key)
        return self.cache[key]

    def put(self, key: str, value):
        if key in self.cache:
            self.cache[key] = value
            self._remove(key)
            self._add_to_front(key)
        else:
            if len(self.cache) >= self.capacity:
                # Remove least recently used (tail)
                lru_key = self.tail
                self._remove(lru_key)
                del self.cache[lru_key]
            self.cache[key] = value
            self._add_to_front(key)
